import sys

def main():
    lines = sys.stdin.read().splitlines()
    s = lines[0].strip()
    k = int(lines[1].strip())

    n = len(s)
    if n % k != 0:
        print("NO")
        return

    segment_len = n // k
    possible = True
    for i in range(0, n, segment_len):
        segment = s[i:i+segment_len]
        if segment != segment[::-1]:
            possible = False
            break

    if possible:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
